export const periodSchema: z.ZodType<FhirPeriod> = z.lazy(() =>
  z
    .strictObject({
      id: z.string().optional(),
      extension: z
        .lazy(() => extensionSchema)
        .array()
        .optional(),
      start: dateTimeSchema.optional(),
      _start: z.lazy(() => elementSchema).optional(),
      end: dateTimeSchema.optional(),
      _end: z.lazy(() => elementSchema).optional(),
    })
    .refine(
      (value) => {
        const period = value as { start?: string; end?: string }
        if (period.start === undefined || period.end === undefined) return true
        const start = fhirDateTimeToEpoch(period.start)
        const end = fhirDateTimeToEpoch(period.end)
        // A malformed endpoint is a malformed date, not an ordering fault; the release says
        // as much with start.hasValue(). Reporting both would name the wrong problem.
        if (Number.isNaN(start) || Number.isNaN(end)) return true
        return start <= end
      },
      { message: 'Period.start must not be later than Period.end.' },
    ),
)

