export const base64BinarySchema: z.ZodType<string> = z
  .string()
  .regex(
    new RegExp('^[0-9a-zA-Z+/= \\t\\n\\r]*$'),
    'Expected a FHIR base64Binary.',
  )
  .refine((value) => value.replace(/[ \t\n\r]/gu, '').length % 4 === 0, {
    message: 'Expected a FHIR base64Binary.',
  })

export const booleanSchema: z.ZodType<boolean> = z.boolean()

export const canonicalSchema: z.ZodType<string> = z
  .string()
  .regex(new RegExp('^(?:[^ \\t\\n\\r]*)$'), 'Expected a FHIR canonical.')

export const codeSchema: z.ZodType<string> = z
  .string()
  .regex(
    new RegExp('^(?:[^ \\t\\n\\r]+([ \\t\\n\\r][^ \\t\\n\\r]+)*)$'),
    'Expected a FHIR code.',
  )

export const dateSchema: z.ZodType<string> = z
  .string()
  .regex(
    new RegExp(
      '^(?:([0-9]([0-9]([0-9][1-9]|[1-9]0)|[1-9]00)|[1-9]000)(-(0[1-9]|1[0-2])(-(0[1-9]|[1-2][0-9]|3[0-1]))?)?)$',
    ),
    'Expected a FHIR date.',
  )

export const dateTimeSchema: z.ZodType<string> = z
  .string()
  .regex(
    new RegExp(
      '^(?:([0-9]([0-9]([0-9][1-9]|[1-9]0)|[1-9]00)|[1-9]000)(-(0[1-9]|1[0-2])(-(0[1-9]|[1-2][0-9]|3[0-1])(T([01][0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|(\\+|-)((0[0-9]|1[0-3]):[0-5][0-9]|14:00)))?)?)?)$',
    ),
    'Expected a FHIR dateTime.',
  )

export const decimalSchema: z.ZodType<number> = z
  .number()
  .refine(
    (value) =>
      new RegExp('^(?:-?(0|[1-9][0-9]*)(\\.[0-9]+)?([eE][+-]?[0-9]+)?)$').test(
        String(value),
      ),
    {
      message: 'Expected a valid FHIR decimal.',
    },
  )

export const idSchema: z.ZodType<string> = z
  .string()
  .regex(new RegExp('^(?:[A-Za-z0-9\\-\\.]{1,64})$'), 'Expected a FHIR id.')

export const instantSchema: z.ZodType<string> = z
  .string()
  .regex(
    new RegExp(
      '^(?:([0-9]([0-9]([0-9][1-9]|[1-9]0)|[1-9]00)|[1-9]000)-(0[1-9]|1[0-2])-(0[1-9]|[1-2][0-9]|3[0-1])T([01][0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|(\\+|-)((0[0-9]|1[0-3]):[0-5][0-9]|14:00)))$',
    ),
    'Expected a FHIR instant.',
  )

export const integerSchema: z.ZodType<number> = z
  .number()
  .int()
  .min(-2147483648)
  .max(2147483647)
  .refine(
    (value) => new RegExp('^(?:-?([0]|([1-9][0-9]*)))$').test(String(value)),
    {
      message: 'Expected a valid FHIR integer.',
    },
  )

export const markdownSchema: z.ZodType<string> = z
  .string()
  .regex(new RegExp('^(?:[\\s\\S]+)$'), 'Expected a FHIR markdown.')

export const oidSchema: z.ZodType<string> = z
  .string()
  .regex(
    new RegExp('^(?:urn:oid:[0-2](\\.(0|[1-9][0-9]*))+)$'),
    'Expected a FHIR oid.',
  )

export const positiveIntSchema: z.ZodType<number> = z
  .number()
  .int()
  .min(-2147483648)
  .max(2147483647)
  .refine((value) => new RegExp('^(?:[1-9][0-9]*)$').test(String(value)), {
    message: 'Expected a valid FHIR positiveInt.',
  })

export const stringSchema: z.ZodType<string> = z
  .string()
  .regex(new RegExp('^(?:[\\s\\S]+)$'), 'Expected a FHIR string.')

export const timeSchema: z.ZodType<string> = z
  .string()
  .regex(
    new RegExp(
      '^(?:([01][0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?)$',
    ),
    'Expected a FHIR time.',
  )

export const unsignedIntSchema: z.ZodType<number> = z
  .number()
  .int()
  .min(-2147483648)
  .max(2147483647)
  .refine(
    (value) => new RegExp('^(?:[0]|([1-9][0-9]*))$').test(String(value)),
    {
      message: 'Expected a valid FHIR unsignedInt.',
    },
  )

export const uriSchema: z.ZodType<string> = z
  .string()
  .regex(new RegExp('^(?:[^ \\t\\n\\r]*)$'), 'Expected a FHIR uri.')

export const urlSchema: z.ZodType<string> = z
  .string()
  .regex(new RegExp('^(?:[^ \\t\\n\\r]*)$'), 'Expected a FHIR url.')

export const uuidSchema: z.ZodType<string> = z
  .string()
  .regex(
    new RegExp(
      '^(?:urn:uuid:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$',
    ),
    'Expected a FHIR uuid.',
  )

export const xhtmlSchema: z.ZodType<string> = z.string()

